// dipakai drawFace(): pointer ke frame ke-n (aman, langsung dari flash)
static inline const uint8_t* dasaiFrame(uint8_t n) {
  if (n >= DASAI_FRAME_COUNT) n = 0;
  return DASAI_FRAMES + (uint32_t)n * DASAI_FRAME_BYTES;
}
